Particle:type=[pos:vec3 vel:vec3 age:float64]
step=(@particles:array<Particle> dt:float64):>void=>{
loop i in [0..particles.length) {
particles[i].pos += particles[i].vel*dt
particles[i].age += dt
}
}
main=()=>{
let particles=[loop i in [0..250000) Particle[vec3(i%100 i%77 i%31) vec3(0.1 0.2 -0.3) 0.0]]
let allocations=alloc_count() let start=time_ns()
loop frame in [0..60) step(@particles 1.0/60.0)
let elapsed=time_ns()-start let extra=alloc_count()-allocations
let total=0.0
loop particle in particles total+=particle.pos.x+particle.pos.y+particle.pos.z+particle.age
printl"{elapsed} {extra} {total}"
}

